from flask import Flask, request, render_template

app = Flask(__name__)
app.jinja_env.autoescape = True  # 显式确保自动转义开启（Flask 对 .html 模板默认已开启）

# 告警订阅页：订阅人名称仅作为变量值传入模板渲染上下文
@app.route("/alert/subscribe", methods=["GET", "POST"])
def alert_subscribe():
    # 外部输入入口：订阅人名称来自请求参数
    if request.method == "POST":
        name = request.form.get("name", "")
    else:
        name = request.args.get("name", "")
    # 防御：白名单校验，仅允许字母数字与下划线，超长则回退默认值
    if not name or len(name) > 32 or not all(c.isalnum() or c == "_" for c in name):
        name = "anonymous"
    # name 仅作为 render_template 的关键字变量值；模板文件固定为 page.html，
    # 不使用 render_template_string / from_string，也不使用 |safe 或 Markup
    return render_template("page.html", name=name)

if __name__ == "__main__":
    app.run(debug=False)
